"""Run the full traffic QAOA with actual finite-shot objectives."""

import math
from dataclasses import dataclass
from typing import cast

import torch

import flagquantum as fq
from examples.synthesis.applications.telecom.network_traffic_optimization.main import (
    build_program,
)
from flagquantum.algorithms import CobylaOptimizer

from . import problem


def initial_parameters() -> tuple[float, ...]:
    return tuple(
        value
        for layer in range(5)
        for value in (
            math.pi * (2 * layer + 1) / 10,
            math.pi * (1 - (2 * layer + 1) / 10),
        )
    )


def physical_to_logical(words: torch.Tensor) -> torch.Tensor:
    out = torch.zeros_like(words)
    for bit in range(24):
        out |= ((words >> bit) & 1) << (23 - bit)
    return out


def draw(parameters: tuple[float, ...], generator: torch.Generator) -> torch.Tensor:
    program = build_program(parameters)
    state = cast(torch.Tensor, fq.run(program).statevector()).reshape(-1)
    probabilities = state.abs().square()
    physical = torch.multinomial(
        probabilities, problem.SHOTS, replacement=True, generator=generator
    )
    return physical_to_logical(physical)


class _QueryBudgetError(Exception):
    """Stop at the original SciPy transcript's twelve-query minimum."""


@dataclass(frozen=True)
class Result:
    trace: tuple[tuple[tuple[float, ...], float], ...]
    parameters: tuple[float, ...]
    counts: tuple[tuple[int, int], ...]
    feasible: tuple[tuple[int, int], ...]
    classical_word: int
    classical_objective: int
    classical_latency: int
    stopped: bool
    converged: bool


def optimize() -> Result:
    classical_word, objective, latency = problem.classical()
    generator = torch.Generator().manual_seed(10)
    trace: list[tuple[tuple[float, ...], float]] = []

    def evaluate(params: torch.Tensor) -> torch.Tensor:
        if len(trace) >= problem.QUERIES:
            raise _QueryBudgetError()
        parameters = tuple(float(p) for p in params)
        cost = float(problem.values(draw(parameters, generator))[0].mean())
        trace.append((parameters, cost))
        return torch.tensor(cost, dtype=torch.float64)

    stopped = converged = False
    try:
        result = CobylaOptimizer(maxiter=100, rhobeg=1.0, rhoend=1e-8).minimize(
            evaluate, torch.tensor(initial_parameters(), dtype=torch.float64)
        )
        converged = result.converged
    except _QueryBudgetError:
        stopped = True
    parameters = min(trace, key=lambda row: row[1])[0]
    words, counts = torch.unique(draw(parameters, generator), return_counts=True)
    order = torch.argsort(counts, descending=True, stable=True)
    ordered = tuple((int(words[i]), int(counts[i])) for i in order)
    _, flow, overlap = problem.values(words)
    good = {
        int(word)
        for word, one, two in zip(words, flow, overlap, strict=True)
        if not int(one) and not int(two)
    }
    feasible = tuple((word, count) for word, count in ordered if word in good)
    return Result(
        tuple(trace),
        parameters,
        ordered,
        feasible,
        classical_word,
        objective,
        latency,
        stopped,
        converged,
    )

"""Original six-node, eight-edge, three-demand traffic model."""

from itertools import product

import torch

NODES = ("A", "B", "C", "D", "E", "F")
EDGES = (
    ("A", "B"),
    ("A", "C"),
    ("B", "E"),
    ("B", "D"),
    ("C", "E"),
    ("C", "D"),
    ("D", "F"),
    ("E", "F"),
)
LATENCY = (2, 3, 2, 1, 1, 2, 2, 1)
# The original MILP c vector retains the insertion order before graph.edges().
MILP_LATENCY = (2, 2, 3, 1, 1, 2, 2, 1)
DEMANDS = (("A", "E"), ("B", "F"), ("C", "F"))
WIDTH, LAYERS, SHOTS, QUERIES = 24, 5, 10_000, 12
POSITIONS = {
    "A": (0.0, 0.6),
    "B": (1.0, 1.1),
    "C": (1.0, 0.1),
    "D": (2.0, 0.6),
    "E": (2.0, 1.1),
    "F": (3.0, 0.6),
}


def values(words: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    bits = ((words[:, None] >> torch.arange(WIDTH)) & 1).reshape(-1, 3, 8)
    objective = (bits * torch.tensor(LATENCY, dtype=torch.float64)).sum(dim=(1, 2)) / 15
    residual = torch.zeros(words.numel(), dtype=torch.int64)
    for demand, (source, target) in enumerate(DEMANDS):
        for node in NODES:
            flow = torch.full(
                (words.numel(),),
                int(node == source) - int(node == target),
                dtype=torch.int64,
            )
            for edge, (first, second) in enumerate(EDGES):
                if node == second:
                    flow += bits[:, demand, edge]
                if node == first:
                    flow -= bits[:, demand, edge]
            residual += flow.square()
    overlap = (bits.sum(dim=1) >= 2).sum(dim=1)
    return objective + 0.2 * (residual + overlap).to(torch.float64), residual, overlap


def cost(word: int) -> float:
    return float(values(torch.tensor([word], dtype=torch.int64))[0][0])


def valid(word: int) -> bool:
    _, flow, overlap = values(torch.tensor([word], dtype=torch.int64))
    return not int(flow[0]) and not int(overlap[0])


def chosen_edges(word: int, demand: int) -> tuple[tuple[str, str], ...]:
    return tuple(
        edge for index, edge in enumerate(EDGES) if word >> (8 * demand + index) & 1
    )


def classical() -> tuple[int, int, int]:
    """Enumerate the original integral flow constraints exactly."""
    choices = []
    for source, sink in DEMANDS:
        masks = []
        for mask in range(256):
            good = True
            for node in NODES:
                flow = int(node == source) - int(node == sink)
                flow += sum(
                    (mask >> i) & 1
                    for i, (_, target) in enumerate(EDGES)
                    if target == node
                )
                flow -= sum(
                    (mask >> i) & 1
                    for i, (first, _) in enumerate(EDGES)
                    if first == node
                )
                good &= flow == 0
            if good:
                masks.append(mask)
        choices.append(masks)
    feasible = []
    for assignments in product(*choices):
        if any(
            assignments[i] & assignments[j] for i in range(3) for j in range(i + 1, 3)
        ):
            continue
        word = sum(mask << (8 * i) for i, mask in enumerate(assignments))
        milp = sum(
            MILP_LATENCY[edge]
            for mask in assignments
            for edge in range(8)
            if mask >> edge & 1
        )
        latency = sum(
            LATENCY[edge]
            for mask in assignments
            for edge in range(8)
            if mask >> edge & 1
        )
        feasible.append((milp, latency, word))
    minimum = min(row[0] for row in feasible)
    # Retain the source MILP objective, including its independent coefficient order.
    selected = min(row for row in feasible if row[0] == minimum)
    return selected[2], selected[0], selected[1]
